import{_ as t,l as i,o as e,c as l,v as r,p as s,x as n,d as c,i as d,S as u}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"Mercury 商用扩散 LM","description":"","frontmatter":{"title":"Mercury 商用扩散 LM","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mercury-diffusion-lm.md","filePath":"llm/mercury-diffusion-lm.md","lastUpdated":1789023840000}'),m={name:"llm/mercury-diffusion-lm.md"};function p(h,a,A,M,E,f){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="mercury-商用扩散-lm" tabindex="-1">Mercury 商用扩散 LM <a class="header-anchor" href="#mercury-商用扩散-lm" aria-label="Permalink to &quot;Mercury 商用扩散 LM&quot;">​</a></h1><div class="epigraph"><p>当提示到来，答案不是从左到右弹出下一个 token，而是从噪声粗到细地改许多位置；Transformer 仍然是去噪网络，换掉的是因式分解与采样循环。</p><footer>—— Inception Labs，Introducing Mercury；Khanna et al., Mercury: Ultra-Fast Language Models Based on Diffusion，arXiv:2506.17298</footer></div><p>2025 年 2 月 Inception Labs 把 <strong>Mercury</strong> 写成「第一套商用规模的扩散大语言模型（dLLM）」。相对 <a href="/llm/llada">LLaDA</a>、<a href="/llm/mdlm">MDLM</a> 一类研究检查点，Mercury 的产品主张是：在 NVIDIA H100 上达到每秒逾千 token 的吞吐，质量对标当时的速度档自回归模型，并提供 playground 与 API。技术报告聚焦编码产品 <strong>Mercury Coder Mini / Small</strong>；公司博文与后续产品页把同一家族扩展到聊天、推理档与 Edit 变体。本篇只引用官方介绍博文、技术报告与公开价目/模型页，<strong>不编总参、层数或词表</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自回归生成每个 token 都要跑一遍网络，且必须等前一个 token 写完。速度档模型把宽度与 KV 压下去，仍受这条串行链限制； Groq / Cerebras 一类专用推理芯片用硬件换吞吐，算法仍是左到右。编码助手、补全、智能体环对延迟极敏感：用户多等 200ms 就会换模型。扩散在图像里已经证明「并行改整幅画」；离散文本上长期停在小模型困惑度，缺一套能当 API 卖的规模与服务栈。</p><p>Inception 要证明的产品命题是：dLLM 可以当自回归 LLM 的 <strong>drop-in</strong>：同一套提示、工具、RAG、SFT/RLHF 数据习惯，只把损失换成去噪目标，把采样换成粗到细的并行改写。若质量明显弱于 Haiku / GPT-4o mini 一档，速度没有客户；若不能走通用 GPU，速度故事会被专用芯片收走。</p><h3 id="粗到细不是「一次前向打出整段」" tabindex="-1">粗到细不是「一次前向打出整段」 <a class="header-anchor" href="#粗到细不是「一次前向打出整段」" aria-label="Permalink to &quot;粗到细不是「一次前向打出整段」&quot;">​</a></h3><p>扩散仍要多步。每一步 Transformer 看当前噪声序列（或掩码序列），并行预测许多位置，再按调度留下一部分、重噪其余。步数决定质量—延迟权衡。报告强调：相对先前小规模离散扩散，他们在数据与计算上做了能扩到万亿 token 量级的修改，但<strong>没有公开</strong>逐步超参、噪声表或网络宽度。能写进方法栏的是过程形状，不是可复现配方。</p><p><span class="marginnote">Artificial Analysis 在 H100 上测 Mini <strong>1109</strong> tok/s、Small <strong>737</strong> tok/s（约 1k 进 / 1k 出的编码负载）。对照表里 Gemini 2.0 Flash-Lite 约 201、Claude 3.5 Haiku 约 61、GPT-4o mini 约 59。吞吐是 API 墙钟，不是单核 FLOPs。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前向把干净 token 序列逐步加噪到已知先验；反向从先验采样，用 \\(p_\\theta(x\\mid z_t)\\) 去噪。报告把训练损失写成对噪声水平加权的重建交叉熵，并称方法扩展自离散扩散文献（报告引用含 Lou 等一类工作），细节留在「对数据与计算的修改」这一句。骨干明确是 <strong>Transformer</strong>：扩散约束的是训练与生成算法，不禁止用注意力实现去噪器。因此 FlashAttention、编译栈、现成并行策略可以借；不能借的是 KV cache 式逐步解码——可见集合每步都在变。</p><h3 id="mercury-coder-公开表" tabindex="-1">Mercury Coder 公开表 <a class="header-anchor" href="#mercury-coder-公开表" aria-label="Permalink to &quot;Mercury Coder 公开表&quot;">​</a></h3><p>报告 Table 1（部分为 AA 标注）：Mini HumanEval 88.0、MBPP 77.1、EvalPlus 78.6、MultiPL-E 74.1、LiveCodeBench 17.0、BigCodeBench 42.0；Small 对应 90.0 / 76.6 / 80.4 / 76.2 / 25.0 / 45.5。Fill-in-the-middle 是扩散的结构性长处：Mini 单行/随机跨度平均在报告 FIM 表里明显高于同档自回归速度模型。Copilot Arena 上 Mini 质量并列第二、速度最快——这是偏好与延迟的产品证据，不是 SWE-bench agent 脚手架。上下文：开箱最多 <strong>32,768</strong> token，用外推协议可到 128k；这是报告声明，不是百万级窗口。</p>',13)),(e(),s(u,null,{default:n(()=>[d(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%8F%90%E7%A4%BA%20%2F%20%E5%89%8D%E7%BC%80%22%5D%20--%3E%20N%5B%22%E5%99%AA%E5%A3%B0%E6%88%96%E6%8E%A9%E7%A0%81%E7%94%BB%E5%B8%83%22%5D%0A%20%20N%20--%3E%20D%5B%22Transformer%20%E5%8E%BB%E5%99%AA%E4%B8%80%E6%AD%A5%22%5D%0A%20%20D%20--%3E%20S%5B%22%E5%B9%B6%E8%A1%8C%E6%94%B9%E5%86%99%E5%A4%9A%20token%22%5D%0A%20%20S%20--%3E%20T%7B%22%E6%9C%AA%E6%94%B6%E6%95%9B%3F%22%7D%0A%20%20T%20--%3E%7C%E6%98%AF%7C%20D%0A%20%20T%20--%3E%7C%E5%90%A6%7C%20Y%5B%22%E7%AD%94%E6%A1%88%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h3 id="服务与兼容" tabindex="-1">服务与兼容 <a class="header-anchor" href="#服务与兼容" aria-label="Permalink to &quot;服务与兼容&quot;">​</a></h3><p>报告写：自研推理引擎做动态 batch 与分页采样，并暴露 OpenAI 兼容 API。算法加速与专用芯片正交，可叠加。微调与对齐把自回归损失换成去噪损失，仍可用 SFT / RLHF / DPO 习惯。企业路径含 API 与本地部署。后续公司产品页把 <strong>Mercury 2</strong> 标成推理 dLLM，<strong>Mercury Edit 2</strong> 走 FIM / next-edit 端点；价目公开例：Mercury 2 输入 $0.25 / 百万、输出 $0.75 / 百万，聊天上下文 128K。那是 2026 年价目快照，与 2025 年 Coder 报告不是同一检查点。引用时写产品名与日期。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>并行改写提高算术强度：一步里许多位置同时要算，GPU 不再为单个 token 的带宽墙空转。这与单用户本地解码最合拍；高 QPS 云上自回归可以靠大 batch 把算力喂饱，扩散的相对优势会收窄——Google 后来在 DiffusionGemma 博文里把同一几何讲得更直白。Mercury 报告把「最大利用通用 GPU」写成系统原因，并把自定义核留在专有引擎里，<strong>没有</strong>开源采样核。</p><p>质量机制来自双向上下文与可改写：填空、修错、格式闭合不必等左到右因果。代价是步数超参：步少则快但粗，步多则接近自回归延迟。公开材料没有给出默认 NFE。推理链可以短，因为「想」也可以并行改，而不必先吐一万个思维 token——这是博文对 agent / 推理的展望，不是已公开的 o 系列对照实验。</p><p><span class="marginnote">参数量未公开。不要把 Mini/Small 当成 7B/14B 的别名。对照表里的 Qwen 2.5 Coder 7B 是开权参照，不是 Mercury 的宽度声明。</span></p><h3 id="和学术掩码扩散的距离" tabindex="-1">和学术掩码扩散的距离 <a class="header-anchor" href="#和学术掩码扩散的距离" aria-label="Permalink to &quot;和学术掩码扩散的距离&quot;">​</a></h3><p>LLaDA 公开 8B、2.3T、损失公式与采样伪代码。Mercury 公开的是产品吞吐、编码榜与「Transformer + 去噪损失」。两者都是离散扩散家族，但 Mercury 不是 LLaDA 的商用包装：数据、步数、是否半自回归块，均未在报告里钉死。不要用 LLaDA 的 \\(1/t\\) 加权去「补全」Mercury 的训练目标。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>无开源权重则不能复现核。32k 开箱窗口不够长代理仓库。LiveCodeBench 上 Mini 17.0 低于若干速度档闭源模型，编码故事不是全面碾压，主轴是 Pareto 上的速度。后续 Mercury 2 的「推理 dLLM」若只有产品页数字，应另开一篇，不要把 2025 年 Coder 表当成 2026 年推理档。API 兼容不等于 KV cache 语义兼容：流式输出可能是逐步揭开，而不是 token-by-token 因果。</p><p>出处：Stefano Ermon，<em>Introducing Mercury</em>，inceptionlabs.ai；Khanna 等，arXiv:2506.17298。价目以 docs.inceptionlabs.ai 当时页为准。</p><p><span class="marginnote">「第一套商用规模 dLLM」是公司自称。学术上更早的有 SEDD、MDLM、LLaDA；商用指可售 API / 本地部署与 H100 上千 tok/s 的产品定位。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Mercury 是 Inception 的商用扩散 LM：Transformer 去噪、并行粗到细生成，主打 H100 上千 tok/s。</li><li>公开最完整的是 Mercury Coder Mini/Small 的编码榜与 AA 吞吐；参数量未公开。</li><li>产品合同是 OpenAI 兼容 API、可 SFT/对齐；采样引擎专有。</li><li>后续 Mercury 2 / Edit 2 是同一家族的产品迭代，引用须写清名称与日期。</li><li>出处：官方博文与 arXiv:2506.17298。不编架构表。</li></ul>',14))])}const P=t(m,[["render",p]]);export{g as __pageData,P as default};
